CREATE TABLE rooms (id BIGSERIAL PRIMARY KEY, name TEXT UNIQUE NOT NULL, location TEXT NOT NULL);
CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','room_operator')), assigned_room_id BIGINT REFERENCES rooms(id), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE devices (id BIGSERIAL PRIMARY KEY, device_name TEXT UNIQUE NOT NULL, api_key_hash TEXT NOT NULL, room_id BIGINT NOT NULL REFERENCES rooms(id), is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE ac_states (room_id BIGINT PRIMARY KEY REFERENCES rooms(id), is_on BOOLEAN NOT NULL DEFAULT FALSE, target_temperature_c REAL NOT NULL DEFAULT 24, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE readings (id BIGSERIAL PRIMARY KEY, device_id BIGINT NOT NULL REFERENCES devices(id), room_id BIGINT NOT NULL REFERENCES rooms(id), recorded_at TIMESTAMPTZ NOT NULL, temperature_c REAL NOT NULL, humidity_percent REAL NOT NULL, co2_ppm INTEGER NOT NULL, pm25_ug_m3 REAL NOT NULL, occupancy INTEGER NOT NULL);
CREATE TABLE alerts (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), reading_id BIGINT REFERENCES readings(id), severity TEXT NOT NULL, message TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE control_commands (id BIGSERIAL PRIMARY KEY, room_id BIGINT NOT NULL REFERENCES rooms(id), issued_by_user_id BIGINT NOT NULL REFERENCES users(id), command_type TEXT NOT NULL, value TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
